def add_common_args(parser):
    """Arguments shared by every model; defaults are those of Time-Series-Library, which the official baseline scripts assume."""
    parser.add_argument("--is_training", type=int, default=1, help="1: train and test; 2: test the latest checkpoint (or --checkpoint N)")
    parser.add_argument("--model_id", type=str, default="test", help="model id")
    parser.add_argument("--model", type=str, default=None, help="model name: DLT, DLTPlug, S_Mamba, iTransformer, PatchTST, RLinear, DLinear, TiDE")
    parser.add_argument("--seed", "--fix_seed", dest="seed", type=int, default=2021, help="seed of python / numpy / torch (and of random neighbours)")
    parser.add_argument("--des", type=str, default="test", help="run description; result rows and checkpoints are keyed by it")

    parser.add_argument("--data", type=str, default="custom", help="dataset class: ETTh1, ETTh2, ETTm1, ETTm2, custom, PEMS, Solar")
    parser.add_argument("--root_path", type=str, default="./data/electricity/", help="root path of the data file")
    parser.add_argument("--data_path", type=str, default="electricity.csv", help="data file")
    parser.add_argument("--features", type=str, default="M", help="M: multivariate -> multivariate, S: univariate, MS: multivariate -> univariate")
    parser.add_argument("--target", type=str, default="OT", help="target feature in S or MS task")
    parser.add_argument("--freq", type=str, default="h", help="freq of the time features: s, t, h, d, b, w, m")
    parser.add_argument("--checkpoints", type=str, default="./temp/checkpoints/", help="checkpoint root")
    parser.add_argument("--checkpoint", type=int, default=0, help="checkpoint seq number to load (0 = train from scratch)")
    parser.add_argument("--keep_checkpoint", type=int, default=1, help="keep the numbered checkpoint after the run (0 = delete it)")
    parser.add_argument("--save_tmp", type=int, default=1, help="save predictions, metrics and plots under temp/ (0 = skip)")
    parser.add_argument("--no_save_preds", dest="save_tmp", action="store_const", const=0, help="same as --save_tmp 0")
    parser.add_argument("--result_file", type=str, default="", help="TSV result store of this run (default: see src/utils/result_io.py)")

    parser.add_argument("--seq_len", type=int, default=96, help="input sequence length")
    parser.add_argument("--label_len", type=int, default=48, help="start token length")
    parser.add_argument("--pred_len", type=int, default=96, help="prediction sequence length")
    parser.add_argument("--inverse", action="store_true", default=False, help="test metrics on the original scale")

    parser.add_argument("--enc_in", type=int, default=7, help="encoder input size")
    parser.add_argument("--dec_in", type=int, default=7, help="decoder input size")
    parser.add_argument("--c_out", type=int, default=7, help="output size")
    parser.add_argument("--d_model", type=int, default=512, help="dimension of model")
    parser.add_argument("--n_heads", type=int, default=8, help="num of heads")
    parser.add_argument("--e_layers", type=int, default=2, help="num of encoder layers")
    parser.add_argument("--d_layers", type=int, default=1, help="num of decoder layers")
    parser.add_argument("--d_ff", type=int, default=2048, help="dimension of fcn")
    parser.add_argument("--moving_avg", type=int, default=25, help="window size of moving average")
    parser.add_argument("--factor", type=int, default=1, help="attn factor")
    parser.add_argument("--distil", action="store_false", default=True, help="whether to use distilling in encoder")
    parser.add_argument("--dropout", type=float, default=0.1, help="dropout")
    parser.add_argument("--embed", type=str, default="timeF", help="time features encoding: timeF, fixed, learned")
    parser.add_argument("--activation", type=str, default="gelu", help="activation")
    parser.add_argument("--use_norm", type=int, default=1, help="instance normalisation of iTransformer / S-Mamba / RLinear (1 = on)")
    parser.add_argument("--individual", action="store_true", default=False, help="RLinear: one linear map per variate")

    parser.add_argument("--num_workers", type=int, default=10, help="data loader num workers")
    parser.add_argument("--itr", type=int, default=1, help="experiments times")
    parser.add_argument("--train_epochs", type=int, default=10, help="train epochs")
    parser.add_argument("--batch_size", type=int, default=32, help="batch size of train input data")
    parser.add_argument("--patience", type=int, default=3, help="early stopping patience")
    parser.add_argument("--learning_rate", type=float, default=0.0001, help="optimizer learning rate")
    parser.add_argument("--loss", type=str, default="MSE", help="training loss: MSE or MAE")
    parser.add_argument("--lradj", type=str, default="type1", help="learning rate schedule: type1 (halve every epoch), type2, type3, cosine")
    parser.add_argument("--use_amp", action="store_true", default=False, help="automatic mixed precision")

    parser.add_argument("--use_gpu", action="store_true", default=True, help="use gpu (default: on)")
    parser.add_argument("--no_use_gpu", action="store_false", dest="use_gpu", help="force cpu")
    parser.add_argument("--gpu", type=int, default=0, help="gpu")
    parser.add_argument("--gpu_type", type=str, default="cuda", help="cuda or mps")
    parser.add_argument("--use_multi_gpu", action="store_true", default=False, help="use multiple gpus")
    parser.add_argument("--devices", type=str, default="0,1,2,3", help="device ids of multiple gpus")

    parser.add_argument("--drop_last", action="store_true", help="drop the last incomplete training / validation batch (official iTransformer, S-Mamba, RLinear loaders)")
    parser.add_argument("--test_batch_size", type=int, default=0, help="test batch size (0 = --batch_size); the iTransformer / S-Mamba code tests with 1")
    parser.add_argument("--no_time_marks", action="store_true", help="no time-mark features (x_mark = None), as the iTransformer / S-Mamba code on PEMS and Solar")
    parser.add_argument("--pems_split", type=str, default="tslib", choices=["tslib", "itransformer"], help="PEMS: look-back of val / test windows from the preceding split (tslib) or inside the split (itransformer)")
    parser.add_argument("--vali_inverse", action="store_true", default=False, help="validation loss = MAE on the original scale (TimeMixer PEMS protocol)")
    parser.add_argument("--epoch_test", dest="no_epoch_test", action="store_false", help="print the test loss after every epoch (not used for model selection; the extra pass draws from the RNG, so the run differs from one without it)")
    parser.add_argument("--no_epoch_test", dest="no_epoch_test", action="store_true", help="skip the per-epoch test loss (the default; kept for the job lists)")
    parser.set_defaults(no_epoch_test=True)
